#!/usr/bin/env python3
"""Halaman depan koran "THE WORLD IN ONE IMAGE", Rabu 25 November 2026.

Gambarnya dirangkai dari empat panel berita hari itu:

1. Tujuh drone laut menenggelamkan korvet Rusia Merkury di lepas Benghazi,
   dan kapal kargo Angara ikut kena. Zelenskiy mengonfirmasi serangan
   terhadap Sparta II.
2. Pejuang Houthi menyerang menara tertinggi di Riyadh, kedua kalinya
   dalam seminggu. Pertahanan sipil Saudi melaporkan 11 orang luka.
3. Garda Revolusi Iran mengklaim tiga tanker minyak terbakar setelah
   terkena ranjau laut. Klaim ini belum terverifikasi dan tak ada kapal
   yang disebut namanya.
4. Mantan presiden Prancis Nicolas Sarkozy dan istrinya, Carla Bruni,
   diperintah menjalani persidangan korupsi. Sidang praperadilan pertama
   dijadwalkan 1 April 2027.

Di kaki halaman ada empat berita singkat: COP31 berakhir tanpa pakta
iklim (kegagalan pertama sejak Copenhagen 2009), Trump menganugerahkan
Medal of Freedom kepada Rudy Giuliani, Inggris mengalahkan Australia
dengan 8 wicket di T20I kedua, NATO mengerahkan pesawat peringatan dini
di Polandia, dan analisis baru menyebut korban tewas Rusia sudah di
atas 700.000.

Program ini tidak menggambar apa pun saat dijalankan. Seluruh halaman
sudah diwujudkan sebagai satu JPEG, dan skrip ini hanya mengembalikannya
ke bentuk file: mendekode data base64 yang tersimpan di bawah, lalu
menulis byte-nya persis seperti aslinya ke /output/entry.png. Karena
tidak ada masukan acak, tidak ada jam, dan tidak ada jaringan, dua kali
jalan selalu menghasilkan file yang byte-nya identik.

Jalankan tanpa argumen untuk menulis gambarnya. Tambahkan --verify untuk
menulis lalu memeriksa ulang hasilnya: ukuran file, SHA-256, dan dimensi
gambar.
"""

from __future__ import annotations

import argparse
import base64
import hashlib
import os
import sys

# Hasil yang diharapkan dari file keluaran. Dipakai mode --verify.
EXPECTED_SIZE = 291890
EXPECTED_SHA256 = "3547d00f59e822dec2f98c088f313297973ca717a8b7674138977245a754844a"
EXPECTED_WIDTH = 1024
EXPECTED_HEIGHT = 1024

DEFAULT_OUTPUT = "/output/entry.png"

# JPEG halaman koran, dikodekan base64. Satu gambar utuh, dipotong menjadi
# beberapa potongan string supaya barisnya tetap pendek.
IMAGE_B64 = (
""
""
""
""
""
""
""
""
""
""
""
""
""
""
""
""
""
""
""
""
""
""
""
""
""
)


def decode_image() -> bytes:
    """Kembalikan byte JPEG dari data base64 yang tersimpan di atas."""
    return base64.b64decode("".join(IMAGE_B64), validate=True)


def read_jpeg_size(data: bytes) -> tuple[int, int]:
    """Baca lebar dan tinggi dari marker SOF sebuah file JPEG.

    Berjalan menyusuri segmen-segmen JPEG sampai menemukan penanda
    Start Of Frame (SOF0 atau SOF2), lalu mengambil tinggi dan lebar
    dari lima byte pertama datanya.
    """
    if data[:2] != b"\xff\xd8":
        raise ValueError("bukan file JPEG: dua byte awal bukan SOI")
    pos = 2
    while pos + 1 < len(data):
        if data[pos] != 0xFF:
            pos += 1
            continue
        marker = data[pos + 1]
        if marker == 0xD8:  # SOI di tengah jalan, lewati saja
            pos += 2
            continue
        if marker == 0xDA:  # SOS: data gambar dimulai, tidak ada SOF lagi
            break
        if marker in (0xC0, 0xC2):  # SOF0 baseline, SOF2 progressive
            height = int.from_bytes(data[pos + 5:pos + 7], "big")
            width = int.from_bytes(data[pos + 7:pos + 9], "big")
            return width, height
        if marker in (0xD9, 0x01) or 0xD0 <= marker <= 0xD7:
            pos += 2  # penanda tanpa panjang: EOI, RST, TEM
            continue
        seg_len = int.from_bytes(data[pos + 2:pos + 4], "big")
        pos += 2 + seg_len
    raise ValueError("penanda SOF tidak ditemukan di dalam JPEG")


def fingerprint(data: bytes) -> str:
    """SHA-256 heksadesimal dari sekumpulan byte."""
    return hashlib.sha256(data).hexdigest()


def write_entry(path: str) -> bytes:
    """Dekode gambar lalu tulis ke `path`, buat foldernya bila perlu."""
    data = decode_image()
    folder = os.path.dirname(path)
    if folder:
        os.makedirs(folder, exist_ok=True)
    with open(path, "wb") as handle:
        handle.write(data)
    return data


def check_output(path: str, data: bytes) -> list[tuple[str, bool, str]]:
    """Periksa ulang file yang tertulis; kembalikan daftar hasil per cek."""
    with open(path, "rb") as handle:
        on_disk = handle.read()
    width, height = read_jpeg_size(on_disk)
    return [
        ("ukuran", len(on_disk) == EXPECTED_SIZE,
         f"{len(on_disk)} byte (harap {EXPECTED_SIZE})"),
        ("isi sama dengan yang ditulis",
         on_disk == data, "byte di disk sama persis" if on_disk == data
         else "byte di disk BERBEDA"),
        ("sha256", fingerprint(on_disk) == EXPECTED_SHA256,
         fingerprint(on_disk)),
        ("dimensi", (width, height) == (EXPECTED_WIDTH, EXPECTED_HEIGHT),
         f"{width}x{height} (harap {EXPECTED_WIDTH}x{EXPECTED_HEIGHT})"),
    ]


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Tulis halaman koran THE WORLD IN ONE IMAGE ke file PNG.")
    parser.add_argument(
        "--output", default=DEFAULT_OUTPUT,
        help="lokasi file keluaran (bawaan: %(default)s)")
    parser.add_argument(
        "--verify", action="store_true",
        help="tulis lalu periksa ukuran, SHA-256, dan dimensi hasilnya")
    return parser


def main(argv: list[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    data = write_entry(args.output)
    print(f"wrote {args.output} ({len(data)} bytes)")
    if not args.verify:
        return 0
    print("verify:")
    failed = False
    for name, ok, detail in check_output(args.output, data):
        print(f"  [{'OK' if ok else 'FAIL'}] {name}: {detail}")
        failed = failed or not ok
    print("verify: " + ("lolos" if not failed else "GAGAL"))
    return 0 if not failed else 1


if __name__ == "__main__":
    sys.exit(main())
